package org.acme.library;

import com.tngtech.archunit.junit.AnalyzeClasses;
import com.tngtech.archunit.junit.ArchTest;
import com.tngtech.archunit.lang.ArchRule;

import static com.tngtech.archunit.lang.syntax.ArchRuleDefinition.noClasses;
import static com.tngtech.archunit.library.Architectures.layeredArchitecture;
import static com.tngtech.archunit.library.dependencies.SlicesRuleDefinition.slices;

/**
 * Architecture rules of the Spide design "Library" (clean preset).
 * Generated by Spide — regenerate with /export archunit instead of editing.
 */
@AnalyzeClasses(packages = "org.acme.library")
public class ArchitectureTest {

    /** clean preset. */
    @ArchTest
    static final ArchRule layers =
        layeredArchitecture().consideringOnlyDependenciesInLayers()
            .layer("Ui").definedBy("org.acme.library.web..")
            .layer("Application").definedBy("org.acme.library.app..")
            .layer("Domain").definedBy("org.acme.library.domain..")
            .layer("Infrastructure").definedBy("org.acme.library.persistence..")
            .whereLayer("Ui").mayOnlyBeAccessedByLayers("Infrastructure")
            .whereLayer("Application").mayOnlyBeAccessedByLayers("Ui", "Infrastructure")
            .whereLayer("Domain").mayOnlyBeAccessedByLayers("Ui", "Application", "Infrastructure")
            .whereLayer("Infrastructure").mayOnlyBeAccessedByLayers("Ui")
            .because("ui/infrastructure → application → domain; dependencies point inward");

    /** forbid *Controller → *Repository */
    @ArchTest
    static final ArchRule forbidden_1 =
        noClasses().that().haveNameMatching(".*\\.[^.]*Controller")
            .should().dependOnClassesThat().haveNameMatching(".*\\.[^.]*Repository")
            .because("go through a service");

    /** forbid domain → persistence */
    @ArchTest
    static final ArchRule forbidden_2 =
        noClasses().that().resideInAPackage("org.acme.library.domain..")
            .should().dependOnClassesThat().resideInAPackage("org.acme.library.persistence..")
            .because("forbid domain → persistence");

    @ArchTest
    static final ArchRule no_http_in_domain =
        noClasses().that().resideInAnyPackage("org.acme.library.domain..")
            .should().dependOnClassesThat().haveNameMatching(".*\\.Http[^.]*")
            .because("no Http* in domain");

    @ArchTest
    static final ArchRule no_package_cycles =
        slices().matching("org.acme.library.(*)..").should().beFreeOfCycles();
}
